INSERT INTO trivia_questions (topic, level, type, prompt, payload, perishable, status, verification)
VALUES
  ('The 13 Colonies and the American Revolution', 'younger_kid', 'mc', 'How many original colonies were there when the United States declared independence from Britain?', '{"options":["11","12","13","15"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"There were exactly 13 original colonies when the United States declared independence in 1776; all other options are clearly incorrect."}'::jsonb),
  ('The 13 Colonies and the American Revolution', 'younger_kid', 'mc', 'Which document, signed in 1776, announced that the American colonies were breaking away from British rule?', '{"options":["The U.S. Constitution","The Mayflower Compact","The Declaration of Independence","The Bill of Rights"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The Declaration of Independence was signed in 1776 and formally announced the colonies'' separation from Britain; all other options are clearly wrong (the Constitution was ratified in 1788, the Mayflower Compact in 1620, and the Bill of Rights in 1791)."}'::jsonb),
  ('The 13 Colonies and the American Revolution', 'younger_kid', 'mc', 'Who was the main author of the Declaration of Independence?', '{"options":["George Washington","Benjamin Franklin","John Adams","Thomas Jefferson"],"correctIndex":3}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Thomas Jefferson was the principal author of the Declaration of Independence in 1776; the other options (Washington, Franklin, Adams) were not the main author, making all distractors clearly wrong."}'::jsonb),
  ('The 13 Colonies and the American Revolution', 'younger_kid', 'mc', 'What was the name of the famous midnight ride in 1775 when a colonist warned that British soldiers were coming?', '{"options":["Paul Revere''s Ride","Daniel Boone''s March","Benjamin Franklin''s Journey","John Hancock''s Dash"],"correctIndex":0}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"On the night of April 18–19, 1775, Paul Revere (along with William Dawes and Samuel Prescott) rode to warn colonial militias that British forces were marching; his ride is the famous one celebrated in Longfellow''s poem, and all three distractors are clearly wrong historical figures for this event."}'::jsonb),
  ('The 13 Colonies and the American Revolution', 'younger_kid', 'mc', 'Which colony was the first to be permanently settled by the English, founded at Jamestown in 1607?', '{"options":["Massachusetts","New York","Virginia","Pennsylvania"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Jamestown, founded in 1607, was indeed in the Virginia Colony and is recognized as the first permanent English settlement in America; the other options are clearly wrong."}'::jsonb),
  ('The 13 Colonies and the American Revolution', 'younger_kid', 'mc', 'The colonists had a famous protest in 1773 where they dumped British tea into a harbor. What city did this happen in?', '{"options":["New York City","Philadelphia","Boston","Savannah"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The Boston Tea Party of December 16, 1773, took place in Boston Harbor; all other options are clearly wrong cities."}'::jsonb),
  ('The 13 Colonies and the American Revolution', 'younger_kid', 'mc', 'Who was the commanding general of the American Continental Army during the Revolutionary War?', '{"options":["John Adams","George Washington","Paul Revere","Benjamin Franklin"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"George Washington was appointed Commander-in-Chief of the Continental Army in 1775 and led it throughout the Revolutionary War; all distractors (Adams, Revere, Franklin) held no such command."}'::jsonb),
  ('The 13 Colonies and the American Revolution', 'younger_kid', 'mc', 'The colonists were angry about ''taxation without representation.'' What does that phrase mean?', '{"options":["They wanted lower food prices but no one listened","Britain taxed them but colonists had no say or vote in the British government","The king represented them but refused to collect taxes","Colonists taxed each other without asking Britain"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The phrase \"taxation without representation\" precisely means the colonists were taxed by the British Parliament while having no elected representatives in that body, making option 1 correct and all other options clearly wrong."}'::jsonb),
  ('The 13 Colonies and the American Revolution', 'younger_kid', 'list', 'The original United States was made up of 13 colonies. Can you name all 13 of them?', '{"items":["Connecticut","Delaware","Georgia","Maryland","Massachusetts","New Hampshire","New Jersey","New York","North Carolina","Pennsylvania","Rhode Island","South Carolina","Virginia"],"target":9}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"All 13 original colonies are correctly listed — exactly the right states, no more, no less."}'::jsonb),
  ('The 13 Colonies and the American Revolution', 'younger_kid', 'list', 'The colonists had many complaints against the British king that led them to fight for independence. Name 4 of the major things the British did that made the colonists angry — for example, unfair taxes or laws.', '{"items":["Taxation without representation","Stamp Act","Townshend Acts","Tea Act","Quartering Act","Intolerable Acts","Boston Massacre","Closing Boston Harbor","No trial by jury","Taking away colonial self-government","Forcing colonists to house British soldiers","Sugar Act"],"target":4}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The proposed answer set is accurate and well-supported — all listed items are documented colonial grievances; the question is open-ended and only requires 4, so the answer set serves as a solid, historically defensible key."}'::jsonb),
  ('Elementary math: number sense, place value, and math facts', 'younger_kid', 'mc', 'Which digit is in the thousands place in the number 47,382?', '{"options":["4","7","3","8"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"In 47,382, breaking down the places: 4 is ten-thousands, 7 is thousands, 3 is hundreds, 8 is tens, 2 is ones — so 7 is correctly in the thousands place."}'::jsonb),
  ('Elementary math: number sense, place value, and math facts', 'younger_kid', 'mc', 'What is the value of 8 times 7?', '{"options":["48","54","56","63"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"8 × 7 = 56, and all distractors (48 = 6×8, 54 = 6×9, 63 = 7×9) are clearly wrong."}'::jsonb),
  ('Elementary math: number sense, place value, and math facts', 'younger_kid', 'mc', 'Which of these numbers is the greatest?', '{"options":["52,019","51,990","52,100","51,899"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"52,100 is clearly the largest of the four numbers; all other options are smaller and unambiguously wrong."}'::jsonb),
  ('Elementary math: number sense, place value, and math facts', 'younger_kid', 'mc', 'What is 144 divided by 12?', '{"options":["11","12","13","14"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"144 ÷ 12 = 12, and all other options (11, 13, 14) are clearly incorrect."}'::jsonb),
  ('Elementary math: number sense, place value, and math facts', 'younger_kid', 'mc', 'When you round 3,764 to the nearest hundred, what do you get?', '{"options":["3,700","3,760","3,800","4,000"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"3,764 rounded to the nearest hundred: the tens digit is 6 (≥5), so round up to 3,800. All distractors are clearly wrong (3,700 rounds down incorrectly, 3,760 is to the nearest ten, and 4,000 is to the nearest thousand)."}'::jsonb),
  ('Elementary math: number sense, place value, and math facts', 'younger_kid', 'mc', 'In the number 605,  what does the zero tell you?', '{"options":["There are zero ones","There are zero tens","There are zero hundreds","The number equals zero"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"In 605, the digits represent 6 hundreds, 0 tens, and 5 ones, so the zero in the tens place correctly tells you there are zero tens; all distractors are clearly wrong."}'::jsonb),
  ('Modern Major League Baseball (players, teams, recent seasons)', 'younger_kid', 'mc', 'Which team plays its home games at Dodger Stadium in Los Angeles?', '{"options":["Los Angeles Angels","San Diego Padres","Los Angeles Dodgers","San Francisco Giants"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Dodger Stadium is unambiguously the home of the Los Angeles Dodgers; all other options play at different stadiums (Angels Stadium, Petco Park, and Oracle Park, respectively)."}'::jsonb),
  ('Modern Major League Baseball (players, teams, recent seasons)', 'younger_kid', 'mc', 'Shohei Ohtani is famous for being able to do two things really well in baseball. What are those two things?', '{"options":["Hit home runs and play outfield","Pitch and hit","Catch and run bases","Field and coach"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Shohei Ohtani is universally renowned as a two-way player — an elite pitcher and elite hitter — making option 1 clearly correct; all other options are clearly wrong (he is not a catcher, coach, or defined primarily as an outfielder/baserunner)."}'::jsonb),
  ('Modern Major League Baseball (players, teams, recent seasons)', 'younger_kid', 'mc', 'Which team won the 2022 World Series by defeating the Philadelphia Phillies?', '{"options":["New York Yankees","Atlanta Braves","Los Angeles Dodgers","Houston Astros"],"correctIndex":3}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The Houston Astros defeated the Philadelphia Phillies 4-2 in the 2022 World Series, making this factually correct and all distractors clearly wrong."}'::jsonb),
  ('Modern Major League Baseball (players, teams, recent seasons)', 'younger_kid', 'mc', 'How many players are on the field for the defensive team at one time in a Major League Baseball game?', '{"options":["8","9","10","11"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"In MLB, the defensive team fields exactly 9 players at a time — pitcher, catcher, four infielders, and three outfielders — making 9 the clear and only correct answer."}'::jsonb),
  ('Modern Major League Baseball (players, teams, recent seasons)', 'younger_kid', 'mc', 'Star outfielder Mike Trout has spent most of his MLB career playing for which team?', '{"options":["Seattle Mariners","Texas Rangers","Los Angeles Angels","Oakland Athletics"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Mike Trout has played his entire MLB career with the Los Angeles Angels since his debut in 2011, and all other options are clearly wrong teams."}'::jsonb),
  ('Modern Major League Baseball (players, teams, recent seasons)', 'younger_kid', 'mc', 'Which MLB team is nicknamed ''the Yanks'' and plays its home games in New York City?', '{"options":["New York Mets","New York Yankees","Boston Red Sox","Baltimore Orioles"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The New York Yankees are universally nicknamed \"the Yanks,\" play home games in New York City (Yankee Stadium in the Bronx), and all other options are clearly wrong teams."}'::jsonb),
  ('The books Holes, The Phantom Tollbooth, and Wonder', 'younger_kid', 'mc', 'In the book ''Holes,'' what does Stanley Yelnats and the other boys at Camp Green Lake have to do every single day as punishment?', '{"options":["Run laps around the lake","Dig holes five feet wide and five feet deep","Pick up trash along the road","Chop wood for the camp"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"In Louis Sachar''s ''Holes,'' the boys at Camp Green Lake are required to dig one hole per day, each exactly five feet wide and five feet deep — this is the central premise of the book, and all other options are clearly incorrect."}'::jsonb),
  ('The books Holes, The Phantom Tollbooth, and Wonder', 'younger_kid', 'mc', 'In ''The Phantom Tollbooth,'' what is the name of the young boy who receives the mysterious tollbooth as a gift?', '{"options":["Felix","Milo","Otto","Finn"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"In Norton Juster''s ''The Phantom Tollbooth,'' the protagonist is unambiguously named Milo; all other options (Felix, Otto, Finn) are clearly wrong."}'::jsonb),
  ('The books Holes, The Phantom Tollbooth, and Wonder', 'younger_kid', 'mc', 'In ''Wonder,'' what is the name of the main character who has a facial difference and starts going to a real school for the first time?', '{"options":["Jack","Julian","August","Henry"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"In R.J. Palacio''s ''Wonder,'' the protagonist is August \"Auggie\" Pullman, a boy with a facial difference who attends Beecher Prep for the first time; Jack is a classmate/friend, Julian is the bully, and Henry is another minor character — all clearly wrong options."}'::jsonb),
  ('The books Holes, The Phantom Tollbooth, and Wonder', 'younger_kid', 'mc', 'In ''Holes,'' what is the nickname given to Stanley by the other boys at Camp Green Lake?', '{"options":["Caveman","Zigzag","Squid","Magnet"],"correctIndex":0}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"In Louis Sachar''s ''Holes,'' Stanley Yelnats is given the nickname \"Caveman\" by the other boys at Camp Green Lake; Zigzag, Squid, and Magnet are nicknames of other boys in the group, making them clearly wrong for this question."}'::jsonb),
  ('The books Holes, The Phantom Tollbooth, and Wonder', 'younger_kid', 'mc', 'In ''The Phantom Tollbooth,'' Milo travels to the Kingdom of Wisdom, where two cities are always arguing. One is Dictionopolis, which loves words. What does the other city, Digitopolis, love?', '{"options":["Colors","Music","Numbers","Animals"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"In Norton Juster''s ''The Phantom Tollbooth,'' Digitopolis is ruled by the Mathemagician and is devoted to numbers, contrasting with Dictionopolis''s love of words; all other options are clearly incorrect."}'::jsonb),
  ('The books Holes, The Phantom Tollbooth, and Wonder', 'younger_kid', 'mc', 'In ''Wonder,'' what does August''s sister Via call him at home as a nickname?', '{"options":["Auggie","Augie Bear","Gus","Little A"],"correctIndex":0}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"In R.J. Palacio''s ''Wonder,'' August Pullman is consistently called \"Auggie\" by his family, including his sister Via; the other options (Augie Bear, Gus, Little A) do not appear in the book as her nickname for him."}'::jsonb),
  ('World history: the rise and fall of empires', 'older_kid', 'mc', 'Which ancient empire was ruled by Julius Caesar and later Augustus, and grew to control much of Europe, North Africa, and the Middle East?', '{"options":["The Greek Empire","The Roman Empire","The Persian Empire","The Ottoman Empire"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Julius Caesar and Augustus were Roman leaders, and the Roman Empire did control much of Europe, North Africa, and the Middle East; all distractors are clearly wrong empires from different eras or regions."}'::jsonb),
  ('World history: the rise and fall of empires', 'older_kid', 'mc', 'Genghis Khan founded which massive empire in the early 1200s that eventually became the largest land empire in history?', '{"options":["The Aztec Empire","The British Empire","The Mongol Empire","The Han Empire"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Genghis Khan founded the Mongol Empire around 1206, and it grew to become the largest contiguous land empire in history; all distractors are clearly wrong."}'::jsonb),
  ('World history: the rise and fall of empires', 'older_kid', 'mc', 'The ancient Egyptian empire was ruled by pharaohs and built along which great river that flows through northeastern Africa?', '{"options":["The Amazon River","The Nile River","The Tigris River","The Ganges River"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Ancient Egyptian civilization was definitively built along the Nile River in northeastern Africa; all distractors are clearly wrong (Amazon is in South America, Tigris is in the Middle East, Ganges is in South Asia)."}'::jsonb),
  ('World history: the rise and fall of empires', 'older_kid', 'mc', 'In 1521, Spanish conquistador Hernán Cortés helped bring down which powerful Mesoamerican empire, whose capital city was Tenochtitlan?', '{"options":["The Inca Empire","The Maya Empire","The Olmec Empire","The Aztec Empire"],"correctIndex":3}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Hernán Cortés conquered the Aztec Empire in 1521, whose capital was Tenochtitlan (modern-day Mexico City); the other options are clearly wrong — the Inca were conquered by Pizarro in Peru, the Maya were never fully conquered as a unified empire, and the Olmec civilization collapsed centuries before Cortés."}'::jsonb),
  ('World history: the rise and fall of empires', 'older_kid', 'mc', 'The British Empire once claimed to be so large that ''the sun never sets on it.'' At its peak around 1920, roughly what fraction of the world''s land did it control?', '{"options":["About one-tenth","About one-quarter","About one-half","About three-quarters"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"At its peak (~1920), the British Empire covered roughly 24% of the world''s land area — approximately one-quarter — making option 1 correct; the other options are clearly too low or too high."}'::jsonb),
  ('World history: the rise and fall of empires', 'older_kid', 'mc', 'Which emperor united China for the first time in 221 BC, began building the Great Wall, and gave China its name?', '{"options":["Emperor Kangxi","Emperor Taizong","Kublai Khan","Qin Shi Huang"],"correctIndex":3}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Qin Shi Huang unified China in 221 BC, initiated the Great Wall, and his dynasty''s name \"Qin\" (Ch''in) is the origin of the word \"China\"; the other options are clearly wrong — Kangxi was a Qing emperor, Taizong a Tang emperor, and Kublai Khan a Mongol ruler, none of whom first unified China in 221 BC."}'::jsonb),
  ('World history: the rise and fall of empires', 'older_kid', 'mc', 'The Ottoman Empire, which lasted for about 600 years, had its capital in which city that sits on the border of Europe and Asia?', '{"options":["Baghdad","Cairo","Constantinople","Jerusalem"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Constantinople (modern Istanbul) was the Ottoman capital from 1453 until the empire''s end in 1922, and it uniquely straddles Europe and Asia; the other options are clearly wrong capitals in different regions."}'::jsonb),
  ('World geography and capital cities', 'older_kid', 'mc', 'What is the capital city of Australia?', '{"options":["Sydney","Melbourne","Canberra","Brisbane"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Canberra is definitively the capital of Australia; the other options (Sydney, Melbourne, Brisbane) are major cities but not the capital, making all distractors clearly wrong."}'::jsonb),
  ('World geography and capital cities', 'older_kid', 'mc', 'Which country has the most people in the world?', '{"options":["United States","Russia","India","Brazil"],"correctIndex":2}'::jsonb, true, 'ready', '{"verdict":"ready","notes":"India surpassed China in 2023 to become the world''s most populous country, with over 1.4 billion people; all other options (USA, Russia, Brazil) are clearly wrong."}'::jsonb),
  ('World geography and capital cities', 'older_kid', 'mc', 'Cairo is the capital city of which African country?', '{"options":["Nigeria","Egypt","Kenya","South Africa"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Cairo is unambiguously the capital of Egypt; all distractors (Nigeria→Abuja, Kenya→Nairobi, South Africa→Pretoria/Cape Town/Bloemfontein) are clearly wrong."}'::jsonb),
  ('World geography and capital cities', 'older_kid', 'mc', 'Which continent is the country of Brazil located on?', '{"options":["Africa","Asia","North America","South America"],"correctIndex":3}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Brazil is definitively located on the continent of South America, and all other options (Africa, Asia, North America) are clearly wrong."}'::jsonb),
  ('World geography and capital cities', 'older_kid', 'mc', 'What is the capital of Japan?', '{"options":["Osaka","Kyoto","Tokyo","Hiroshima"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Tokyo is unambiguously the capital of Japan, and all other options (Osaka, Kyoto, Hiroshima) are clearly not the capital."}'::jsonb),
  ('World geography and capital cities', 'older_kid', 'mc', 'Ottawa is the capital city of which country?', '{"options":["Australia","Canada","United Kingdom","New Zealand"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Ottawa is unambiguously the capital of Canada; all other options have different capitals (Canberra, London, and Wellington respectively)."}'::jsonb),
  ('World geography: distances, heights, and sizes', 'older_kid', 'closest', 'How tall is Mount Everest, the highest mountain in the world, in feet?', '{"answer":29032,"unit":"feet"}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"29,032 feet (8,849 m) is the official height of Mount Everest as surveyed and confirmed by China and Nepal in 2020, making the proposed answer correct."}'::jsonb),
  ('World geography: distances, heights, and sizes', 'older_kid', 'closest', 'How many countries are there in the continent of Africa?', '{"answer":54,"unit":"countries"}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Africa has 54 internationally recognized sovereign countries, a well-established and unambiguous fact."}'::jsonb),
  ('World geography: distances, heights, and sizes', 'older_kid', 'closest', 'What is the area of Russia, the largest country in the world, in square miles?', '{"answer":6601668,"unit":"square miles"}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Russia''s area is approximately 6,601,668 square miles (17,098,242 km²), and it is indeed the largest country in the world — both facts are correct."}'::jsonb),
  ('World geography: distances, heights, and sizes', 'older_kid', 'closest', 'How deep is the Mariana Trench, the deepest point in any ocean on Earth, in feet?', '{"answer":36089,"unit":"feet"}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The commonly cited depth of the Mariana Trench''s Challenger Deep is approximately 36,089 feet (10,994 meters by some modern measurements, but 36,089 ft / ~10,994 m is the widely accepted standard figure used in most references)."}'::jsonb),
  ('Fractions, decimals, percents, ratios, and calculating tips', 'older_kid', 'mc', 'What is 3/4 written as a decimal?', '{"options":["0.34","0.57","0.75","0.43"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"3 ÷ 4 = 0.75, and all other options (0.34, 0.57, 0.43) are clearly incorrect."}'::jsonb),
  ('Fractions, decimals, percents, ratios, and calculating tips', 'older_kid', 'mc', 'A shirt costs $40 and is on sale for 25% off. How much money do you save?', '{"options":["$4.00","$8.00","$10.00","$15.00"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"25% of $40 = 0.25 × $40 = $10.00; all other options are clearly wrong."}'::jsonb),
  ('Fractions, decimals, percents, ratios, and calculating tips', 'older_kid', 'mc', 'In a class of 30 students, 18 are girls. What is the ratio of girls to boys, written in simplest form?', '{"options":["3 to 2","18 to 12","2 to 3","9 to 5"],"correctIndex":0}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"30 students minus 18 girls = 12 boys; 18:12 simplifies to 3:2 (dividing both by 6). Option 1 (18 to 12) is the unsimplified form, option 2 (2 to 3) is boys to girls (reversed), and option 3 (9 to 5) is incorrect, so all distractors are clearly wrong."}'::jsonb),
  ('Fractions, decimals, percents, ratios, and calculating tips', 'older_kid', 'mc', 'Your restaurant bill comes to $20. You want to leave an 15% tip. How much should the tip be?', '{"options":["$1.50","$2.00","$3.00","$4.00"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"15% of $20 = 0.15 × $20 = $3.00, which matches option 2; all other options are clearly wrong."}'::jsonb),
  ('Fractions, decimals, percents, ratios, and calculating tips', 'older_kid', 'mc', 'Which of the following is equal to 0.6?', '{"options":["6/100","1/6","3/5","2/6"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"3/5 = 0.6 exactly; the other options (6/100 = 0.06, 1/6 ≈ 0.1667, 2/6 ≈ 0.3333) are all clearly incorrect."}'::jsonb),
  ('Fractions, decimals, percents, ratios, and calculating tips', 'older_kid', 'mc', 'What percent is equivalent to the fraction 7/20?', '{"options":["7%","20%","35%","72%"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"7/20 = 35/100 = 35%, and all other options are clearly incorrect."}'::jsonb),
  ('The San Francisco Giants (last two decades)', 'older_kid', 'mc', 'The San Francisco Giants won three World Series championships in five years. Which years did they win all three of those titles?', '{"options":["2008, 2011, and 2014","2010, 2012, and 2014","2010, 2013, and 2016","2009, 2012, and 2015"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The San Francisco Giants won the World Series in 2010, 2012, and 2014 — three titles in five years — making option 1 clearly correct and all other options clearly wrong."}'::jsonb),
  ('The San Francisco Giants (last two decades)', 'older_kid', 'mc', 'Giants slugger Barry Bonds set the all-time MLB single-season home run record in 2001. How many home runs did he hit that season?', '{"options":["61","70","73","78"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Barry Bonds hit 73 home runs in 2001, breaking Mark McGwire''s record of 70 (set in 1998), which itself broke Roger Maris''s record of 61; 78 is simply a made-up number, making all distractors clearly wrong."}'::jsonb),
  ('The San Francisco Giants (last two decades)', 'older_kid', 'mc', 'The Giants play their home games at a ballpark located right on the water in San Francisco. What is the name of that stadium?', '{"options":["Candlestick Park","Oracle Park","Chase Field","Petco Park"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Oracle Park (formerly AT&T Park, Pacific Bell Park) is the current home of the SF Giants, situated on San Francisco Bay; Candlestick Park was their old stadium (not on the water), Chase Field is in Phoenix, and Petco Park is in San Diego — all clearly wrong options."}'::jsonb),
  ('The San Francisco Giants (last two decades)', 'older_kid', 'mc', 'Tim Lincecum was a two-time NL Cy Young Award winner for the Giants. In which two back-to-back seasons did he win that award?', '{"options":["2006 and 2007","2008 and 2009","2010 and 2011","2012 and 2013"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Tim Lincecum won the NL Cy Young Award in both 2008 and 2009, making option 1 correct; all other year-pairs are clearly wrong."}'::jsonb),
  ('Classical music and composers', 'adult', 'mc', 'Which composer wrote the libretto for his own opera ''Die Meistersinger von Nürnberg,'' in addition to composing the music?', '{"options":["Giuseppe Verdi","Richard Wagner","Hector Berlioz","Richard Strauss"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Richard Wagner was famous for writing his own libretti (which he called \"poems\") for all of his mature operas, including Die Meistersinger von Nürnberg; the other three composers are clearly wrong choices."}'::jsonb),
  ('Classical music and composers', 'adult', 'mc', 'Beethoven''s ''Ode to Joy,'' the choral finale of his Ninth Symphony, sets a poem originally written by which German poet?', '{"options":["Johann Wolfgang von Goethe","Heinrich Heine","Friedrich Schiller","Friedrich Hölderlin"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The \"Ode to Joy\" (An die Freude) was written by Friedrich Schiller in 1785, and Beethoven set it in the finale of his Ninth Symphony; the other three poets (Goethe, Heine, Hölderlin) are all clearly wrong choices."}'::jsonb),
  ('Classical music and composers', 'adult', 'mc', 'The ''Goldberg Variations'' by J. S. Bach were originally composed for which keyboard instrument?', '{"options":["Clavichord","Fortepiano","Harpsichord","Organ"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The Goldberg Variations (BWV 988, 1741) were published as part of the Clavier-Übung IV and explicitly composed for a two-manual harpsichord; the other options are clearly wrong instruments for this work."}'::jsonb),
  ('Classical music and composers', 'adult', 'mc', 'Antonín Dvořák''s Symphony No. 9, subtitled ''From the New World,'' was composed while Dvořák was serving as director of which institution?', '{"options":["The Vienna Conservatory","The Prague National Theatre","The National Conservatory of Music of America in New York","The Royal Academy of Music in London"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Dvořák served as director of the National Conservatory of Music of America in New York from 1892 to 1895, during which time he composed Symphony No. 9 \"From the New World\" (1893); all other options are clearly wrong institutions."}'::jsonb),
  ('Classical music and composers', 'adult', 'mc', 'Franz Schubert''s song cycle ''Die Winterreise'' is a setting of poems by which Romantic poet?', '{"options":["Wilhelm Müller","Joseph von Eichendorff","Ludwig Uhland","Heinrich Heine"],"correctIndex":0}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Schubert''s ''Winterreise'' (1827) is definitively a setting of 24 poems from Wilhelm Müller''s cycle; the other poets (Eichendorff, Uhland, Heine) are clearly wrong options."}'::jsonb),
  ('Classical music and composers', 'adult', 'mc', 'Which 20th-century compositional technique, developed by Arnold Schoenberg, organizes pitch around a fixed series of all twelve tones of the chromatic scale?', '{"options":["Spectralism","Serialism","Minimalism","Microtonalism"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Arnold Schoenberg developed twelve-tone serialism, which organizes pitch using a fixed row of all 12 chromatic tones; the other options (Spectralism, Minimalism, Microtonalism) are clearly distinct techniques unrelated to this description."}'::jsonb),
  ('Pop and rock music history', 'adult', 'mc', 'Which 1966 Beach Boys album, widely regarded as a landmark of studio innovation, was Brian Wilson''s ambitious response to the Beatles'' ''Rubber Soul''?', '{"options":["Today!","Pet Sounds","Smile","Wild Honey"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Pet Sounds (1966) is indeed Brian Wilson''s widely documented ambitious response to the Beatles'' Rubber Soul, and is universally regarded as a landmark of studio innovation; the other options are clearly wrong."}'::jsonb),
  ('Pop and rock music history', 'adult', 'mc', 'Robert Johnson''s mythologized ''deal at the crossroads'' has made him a foundational figure in which genre that directly gave rise to rock and roll?', '{"options":["Appalachian folk","Delta blues","Chicago jazz","Piedmont gospel"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Robert Johnson is indeed the quintessential Delta blues musician, famous for the crossroads legend, and Delta blues directly influenced the development of rock and roll; all distractors are clearly wrong genres for Johnson."}'::jsonb),
  ('Pop and rock music history', 'adult', 'mc', 'Which British producer, known as the ''Fifth Beatle,'' masterminded the orchestral arrangements on ''Eleanor Rigby'' and guided the band through their entire EMI studio career?', '{"options":["Joe Meek","Mickie Most","George Martin","Tony Visconti"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"George Martin produced all of The Beatles'' EMI recordings, arranged the string octet on ''Eleanor Rigby,'' and is widely nicknamed the ''Fifth Beatle''; the other options (Joe Meek, Mickie Most, Tony Visconti) were notable British producers but had no involvement with The Beatles at EMI."}'::jsonb),
  ('Pop and rock music history', 'adult', 'mc', 'Kraftwerk''s 1974 album ''Autobahn'' is credited as a foundational text of electronic pop. From which German city did the band originate?', '{"options":["Berlin","Hamburg","Munich","Düsseldorf"],"correctIndex":3}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Kraftwerk was formed in Düsseldorf in 1969, and all three wrong options (Berlin, Hamburg, Munich) are clearly incorrect."}'::jsonb),
  ('Pop and rock music history', 'adult', 'mc', 'The so-called ''British Invasion'' of the American pop charts is conventionally dated from February 1964, when a specific band made its debut appearance on ''The Ed Sullivan Show.'' Which band was it?', '{"options":["The Rolling Stones","The Kinks","The Beatles","The Who"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The Beatles appeared on The Ed Sullivan Show on February 9, 1964, an event widely recognized as the start of the British Invasion; the other options (Rolling Stones, Kinks, The Who) are clearly wrong as none of them triggered this milestone."}'::jsonb),
  ('Technology and computing history', 'adult', 'mc', 'Which mathematician is widely credited with conceiving the theoretical ''universal computing machine'' in a landmark 1936 paper that laid the conceptual foundation for modern computers?', '{"options":["John von Neumann","Alan Turing","Alonzo Church","Claude Shannon"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Alan Turing introduced the concept of the \"universal computing machine\" (Turing machine) in his landmark 1936 paper \"On Computable Numbers, with an Application to the Entscheidungsproblem,\" which is widely recognized as a foundational work in computer science; the other options, while important figures, are clearly wrong for this specific question."}'::jsonb),
  ('Technology and computing history', 'adult', 'mc', 'In what decade was the ARPANET — the precursor to the modern internet — first successfully demonstrated, with a message sent between UCLA and Stanford?', '{"options":["1950s","1960s","1970s","1980s"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The first ARPANET message was sent on October 29, 1969, between UCLA and the Stanford Research Institute (SRI), firmly placing it in the 1960s; all other options are clearly wrong."}'::jsonb),
  ('Technology and computing history', 'adult', 'mc', 'The first commercially successful spreadsheet program, VisiCalc, was released in 1979 for which personal computer platform?', '{"options":["Commodore PET","TRS-80","Apple II","Altair 8800"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"VisiCalc was indeed first released in 1979 exclusively for the Apple II; ports to other platforms came later, and the Altair 8800 (1975) was well before VisiCalc and never received it."}'::jsonb),
  ('Technology and computing history', 'adult', 'mc', 'Which Intel processor, released in 1971, is widely regarded as the world''s first commercially available single-chip microprocessor?', '{"options":["Intel 8008","Intel 4004","Intel 8080","Intel 6502"],"correctIndex":1}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"The Intel 4004, released in November 1971, is universally recognized as the world''s first commercially available single-chip microprocessor; the 8008 came in 1972, the 8080 in 1974, and the 6502 (not even Intel) in 1975."}'::jsonb),
  ('Technology and computing history', 'adult', 'mc', 'Linus Torvalds announced the first version of the Linux kernel in a 1991 Usenet post, stating the project was ''just a hobby.'' At which university was he studying at the time?', '{"options":["Uppsala University","Aalto University","University of Helsinki","Stockholm University"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"Linus Torvalds was indeed studying at the University of Helsinki when he announced the Linux kernel in August 1991; the other options are clearly wrong institutions."}'::jsonb),
  ('Technology and computing history', 'adult', 'mc', 'The term ''bug'' to describe a computing error was famously popularized after a real moth was found causing a malfunction in which early computer at Harvard University in 1947?', '{"options":["ENIAC","UNIVAC I","Mark II","Colossus"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"In September 1947, a moth was found lodged in a relay of the Harvard Mark II computer, and Grace Hopper''s team taped it into the logbook — this is the well-documented event that popularized the term \"bug\" in computing; the other options (ENIAC, UNIVAC I, Colossus) are all clearly wrong machines."}'::jsonb),
  ('Movies and literature', 'adult', 'mc', 'Which novel by Cormac McCarthy, later adapted into an Academy Award-winning film by the Coen Brothers, follows a hunter who stumbles upon the aftermath of a drug deal gone wrong in the Texas desert?', '{"options":["Blood Meridian","The Road","No Country for Old Men","Outer Dark"],"correctIndex":2}'::jsonb, false, 'ready', '{"verdict":"ready","notes":"No Country for Old Men (2005) by Cormac McCarthy follows hunter Llewelyn Moss who discovers the aftermath of a drug deal gone wrong in the Texas desert; the Coen Brothers'' 2007 film adaptation won four Academy Awards including Best Picture. The other options are clearly wrong: Blood Meridian is set in the 1850s borderlands with a different plot, The Road is a post-apocalyptic story, and Outer Dark is set in Appalachia."}'::jsonb),
